// jrp_rqa_extractor_axi.v: the released RQA_extractor_axi.v (Li, Lai and Oberst 2026, MIT) with the
// core instance renamed to jrp_rqa_extractor. Generated by scripts/derive_extractor.py.

// rqa_extractor_axi.v
// AXI-Lite wrapper for rqa_extractor_online_core.
//
// AXI-Lite map (32-bit):
//  0x00  [RO] ID/version = 0x52514131 ("RQA1")
//  0x04  [RW] STATUS: [0]=metrics_valid_sticky (W1C), [1]=busy (cells_accepted<cells_target), [8]=hist_en
//  0x08  [RO] rr_count_lo
//  0x0C  [RO] rr_count_hi
//  0x10  [RO] det_points_lo
//  0x14  [RO] det_points_hi
//  0x18  [RO] det_lines
//  0x1C  [RO] l_max
//  0x20  [RO] lam_points_lo
//  0x24  [RO] lam_points_hi
//  0x28  [RO] lam_lines
//  0x2C  [RO] v_max
//  0x30  [RO] cells_target
//  0x34  [RO] cells_accepted (exposed by core via internal wire)
//  0x100..  DET histogram bins (idx 0..HIST_K-1)
//  0x200..  LAM histogram bins (idx 0..HIST_K-1)
//
// Writes:
//   STATUS bit0 = 1 clears metrics_valid_sticky.
//   Other writes are ignored.
//
// Connect s_axis_* and frame_start/cells_target as you do for the old RQA.
//
// NOTE: This AXI-Lite is single-beat, no outstanding transactions.


// AXI-Lite wrapper (fixed): proper W1C sticky, consistent 12-bit AXI addresses,
// writable cells_target at 0x30, sane busy, and 1-cycle hist read pipeline.

`timescale 1ns / 1ps
module jrp_rqa_extractor_axi #(
    parameter integer N_MAX       = 8192,
    parameter integer N_BITS      = 14,
    parameter integer RUNW        = 16,
    parameter integer ENABLE_HIST = 1,
    parameter integer HIST_W      = 14,
    parameter integer HIST_K      = 8192
)(
    input  wire                   clk,
    input  wire                   rst_n,

    // frame control / config 
    input  wire                   frame_start,
    input  wire [31:0]            cells_target,   
    input  wire [31:0]            n_actual,
    // cell stream
    input  wire [2*N_BITS:0]      s_axis_tdata,
    input  wire                   s_axis_tvalid,
    output wire                   s_axis_tready,

    // AXI-Lite slave (12-bit byte address)
    input  wire [16:0]            s_axi_awaddr,
    input  wire                   s_axi_awvalid,
    output reg                    s_axi_awready,
    input  wire [31:0]            s_axi_wdata,
    input  wire [3:0]             s_axi_wstrb,
    input  wire                   s_axi_wvalid,
    output reg                    s_axi_wready,
    output reg  [1:0]             s_axi_bresp,
    output reg                    s_axi_bvalid,
    input  wire                   s_axi_bready,

    input  wire [16:0]            s_axi_araddr,
    input  wire                   s_axi_arvalid,
    output reg                    s_axi_arready,
    output reg  [31:0]            s_axi_rdata,
    output reg  [1:0]             s_axi_rresp,
    output reg                    s_axi_rvalid,
    input  wire                   s_axi_rready,
    //input  wire                   finalize_pulse,
    input  wire  [31:0]           l_min,
    input  wire  [31:0]           v_min,
    output wire        metrics_valid_pulse
);

    // --------------------------
    // Address map (byte addresses)
    // --------------------------
    localparam [11:0] ADDR_ID        = 12'h000;
    localparam [11:0] ADDR_STATUS    = 12'h004;
    localparam [11:0] ADDR_RR_LO     = 12'h008;
    localparam [11:0] ADDR_RR_HI     = 12'h00C;
    localparam [11:0] ADDR_DET_LO    = 12'h010;
    localparam [11:0] ADDR_DET_HI    = 12'h014;
    localparam [11:0] ADDR_DET_LINES = 12'h018;
    localparam [11:0] ADDR_L_MAX     = 12'h01C;
    localparam [11:0] ADDR_LAM_LO    = 12'h020;
    localparam [11:0] ADDR_LAM_HI    = 12'h024;
    localparam [11:0] ADDR_LAM_LINES = 12'h028;
    localparam [11:0] ADDR_V_MAX     = 12'h02C;
    localparam [11:0] ADDR_CELLS_TGT = 12'h030;
    localparam [11:0] ADDR_CELLS_ACC = 12'h038; 
    // Histogram windows: 0x100.. (DET), 0x200.. (LAM)
    // Index = [7:2] (word index)
    localparam HIST_EN = (ENABLE_HIST != 0);
    // --------------------------
    // Core signals
    // --------------------------
    wire [63:0] rr_count;
    wire [63:0] det_points;
    wire [31:0] det_lines;
    wire [RUNW-1:0] l_max;
    wire [63:0] lam_points;
    wire [31:0] lam_lines;
    wire [RUNW-1:0] v_max;

    reg                  hist_rd_en;
    reg                  hist_sel;     // 0=DET, 1=LAM
    reg  [$clog2(HIST_K)-1:0] hist_idx;
    wire [31:0]          hist_rd_data;
    wire                 hist_ready;

    reg metrics_valid_sticky;
    reg in_frame; // busy
    reg [31:0] cells_target_reg; 
    wire [31:0] cells_target_eff = (cells_target_reg != 32'd0) ? cells_target_reg : cells_target;
    reg [31:0] cells_target_latched;
    wire [31:0] cells_accepted_dbg;
    reg [31:0] cells_acc_cnt;
    
    
    localparam integer HIST_GUARD_CYC = 128;  
    reg [$clog2(HIST_GUARD_CYC):0] hist_guard_cnt;
    wire hist_guard_busy = (hist_guard_cnt != 0);
    
    always @(posedge clk or negedge rst_n) begin
      if (!rst_n) begin
        hist_guard_cnt <= 0;
      end else begin
        if (metrics_valid_pulse) begin
          hist_guard_cnt <= HIST_GUARD_CYC[$clog2(HIST_GUARD_CYC):0];
        end else if (hist_guard_busy) begin
          hist_guard_cnt <= hist_guard_cnt - 1'b1;
        end
      end
    end

   
    jrp_rqa_extractor #(
        .N_MAX(N_MAX), .N_BITS(N_BITS), .RUNW(RUNW),
        .ENABLE_HIST(ENABLE_HIST), .HIST_W(HIST_W), .HIST_K(HIST_K)
    ) u_core (
        .clk(clk), .rst_n(rst_n),
        .frame_start(frame_start),
        .cells_target(cells_target_latched),
        .n_actual(n_actual),   
        .s_axis_tdata(s_axis_tdata),
        .s_axis_tvalid(s_axis_tvalid),
        .s_axis_tready(s_axis_tready),
        .rr_count(rr_count),
        .det_points(det_points),
        .det_lines(det_lines),
        .l_max(l_max),
        .lam_points(lam_points),
        .lam_lines(lam_lines),
        .v_max(v_max),
        .metrics_valid(metrics_valid_pulse),
        .hist_rd_en(hist_rd_en),
        .hist_sel(hist_sel),
        .hist_idx(hist_idx),
        .hist_rd_data(hist_rd_data),
        .hist_ready(hist_ready),
        .cells_accepted_dbg(cells_accepted_dbg),
        .l_min(l_min),
        .v_min(v_min)
    );

reg w1c_clear_sticky;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        metrics_valid_sticky <= 1'b0;
        in_frame             <= 1'b0;
        cells_target_latched <= 32'd0;
        cells_acc_cnt        <= 32'd0;
    end else begin        
        if (frame_start) begin
            in_frame             <= 1'b1;
            cells_target_latched <= cells_target_eff;
            cells_acc_cnt        <= 32'd0;
        end

        if (s_axis_tvalid && s_axis_tready)
            cells_acc_cnt <= cells_acc_cnt + 1'b1;
        if (metrics_valid_pulse)
            in_frame <= 1'b0;

        if (w1c_clear_sticky)         metrics_valid_sticky <= 1'b0;
        else if (metrics_valid_pulse) metrics_valid_sticky <= 1'b1;
    end
end

wire busy = in_frame ||
            ((cells_target_latched != 32'd0) &&
             (cells_accepted_dbg < cells_target_latched));


    // --------------------------
    // AXI-Lite write channel
    // --------------------------
    reg [16:0] awaddr_q;
    wire       wr_fire = s_axi_awvalid && s_axi_wvalid && s_axi_awready && s_axi_wready;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            s_axi_awready <= 1'b0; s_axi_wready <= 1'b0;
            s_axi_bvalid  <= 1'b0; s_axi_bresp  <= 2'b00;
            awaddr_q      <= 17'd0;
            w1c_clear_sticky <= 1'b0;
            cells_target_reg <= 32'd0;
        end else begin
            w1c_clear_sticky <= 1'b0;

            // AW/W ready
            if (!s_axi_awready && s_axi_awvalid) s_axi_awready <= 1'b1;
            else if (wr_fire)                    s_axi_awready <= 1'b0;

            if (!s_axi_wready  && s_axi_wvalid)  s_axi_wready  <= 1'b1;
            else if (wr_fire)                    s_axi_wready  <= 1'b0;

            // latch address
            if (!s_axi_awready && s_axi_awvalid) awaddr_q <= s_axi_awaddr;

            // do write
            if (wr_fire) begin
                case (awaddr_q[11:0])
                    ADDR_STATUS: begin
                        // bit0 = W1C sticky
                        if (s_axi_wdata[0]) w1c_clear_sticky <= 1'b1;
                    end
                    ADDR_CELLS_TGT: begin
                        // cells_target
                        // WSTRB 
                        if (&s_axi_wstrb) cells_target_reg <= s_axi_wdata;
                        else begin
                            if (s_axi_wstrb[0]) cells_target_reg[ 7:0 ] <= s_axi_wdata[ 7:0 ];
                            if (s_axi_wstrb[1]) cells_target_reg[15:8 ] <= s_axi_wdata[15:8 ];
                            if (s_axi_wstrb[2]) cells_target_reg[23:16] <= s_axi_wdata[23:16];
                            if (s_axi_wstrb[3]) cells_target_reg[31:24] <= s_axi_wdata[31:24];
                        end
                    end
                    default: ; 
                endcase
            end

            // B channel
            if (!s_axi_bvalid && wr_fire) begin
                s_axi_bvalid <= 1'b1; s_axi_bresp <= 2'b00;
            end else if (s_axi_bvalid && s_axi_bready) begin
                s_axi_bvalid <= 1'b0;
            end
        end
    end

// --------------------------
// AXI-Lite read channel
// --------------------------
wire ar_fire = s_axi_arvalid && !s_axi_arready;

// ====== Address window (relative) ======
localparam integer AXI_AW       = 17;            // 128KB window
localparam [AXI_AW-1:0] REG_BASE   = 17'h00000;  // 0x0000
localparam [AXI_AW-1:0] REG_SIZE   = 17'h01000;  // 4KB

localparam integer       BIN_BYTES = 4;
localparam integer       DET_BYTES = HIST_K * BIN_BYTES;   // e.g. 8192*4 = 32KB
localparam [AXI_AW-1:0]  DET_BASE  = 17'h01000;            // 0x1000
localparam [AXI_AW-1:0]  DET_END   = DET_BASE + DET_BYTES; // not inclusive

localparam [AXI_AW-1:0]  LAM_BASE  = DET_END;              
localparam integer       LAM_BYTES = HIST_K * BIN_BYTES;   // same size as DET
localparam [AXI_AW-1:0]  LAM_END   = LAM_BASE + LAM_BYTES; // not inclusive

wire ar_hits_det  = (s_axi_araddr >= DET_BASE) && (s_axi_araddr < DET_END);
wire ar_hits_lam  = (s_axi_araddr >= LAM_BASE) && (s_axi_araddr < LAM_END);
wire ar_hits_hist = ar_hits_det | ar_hits_lam;

wire [16:0] det_idx_shift = s_axi_araddr - DET_BASE;
wire [$clog2(HIST_K)-1:0] det_idx_from_ar =
    det_idx_shift[$clog2(HIST_K)+1:2];  // >>2 
wire [16:0] lam_idx_shift = s_axi_araddr - LAM_BASE;
wire [$clog2(HIST_K)-1:0] lam_idx_from_ar =
    lam_idx_shift[$clog2(HIST_K)+1:2];
    
wire can_accept   = !ar_hits_hist || hist_ready;  

always @(posedge clk or negedge rst_n) begin
  if (!rst_n) begin
    s_axi_arready <= 1'b0;
  end else begin
    if (!s_axi_arready && s_axi_arvalid && can_accept)
      s_axi_arready <= 1'b1;
    else
      s_axi_arready <= 1'b0;
  end
end

always @(posedge clk or negedge rst_n) begin
  if (!rst_n) begin
    hist_rd_en <= 1'b0;
    hist_sel   <= 1'b0;
    hist_idx   <= 0;
  end else begin
    hist_rd_en <= 1'b0;  
    if (ar_fire && ar_hits_hist) begin
        if(ar_hits_det) begin
            hist_sel   <= 1'b0;      // 0=DET, 1=LAM
            hist_idx   <= det_idx_from_ar;
            hist_rd_en <= 1'b1; 
        end else if (ar_hits_lam) begin          
          hist_sel   <= 1'b1;      // 0=DET, 1=LAM
          hist_idx   <= lam_idx_from_ar;
          hist_rd_en <= 1'b1;             // READ_LATENCY_B=1
      end
    end
  end
end

reg        ar_fire_q1, ar_fire_q2;
reg        rd_is_hist_q1, rd_is_hist_q2;
reg [16:0] araddr_q1, araddr_q2;
wire ar_in_reg = (araddr_q1 >= REG_BASE) && (araddr_q1 < (REG_BASE + REG_SIZE));
wire [11:0] reg_off_q1 = araddr_q1[11:0] - REG_BASE[11:0];  
always @(posedge clk or negedge rst_n) begin
  if (!rst_n) begin
    ar_fire_q1 <= 1'b0; rd_is_hist_q1 <= 1'b0; araddr_q1 <= 12'd0;
    ar_fire_q2 <= 1'b0; rd_is_hist_q2 <= 1'b0; araddr_q2 <= 12'd0;
    s_axi_rvalid <= 1'b0; s_axi_rresp <= 2'b00; s_axi_rdata <= 32'd0;
  end else begin
    // q1
    ar_fire_q1    <= ar_fire;
    rd_is_hist_q1 <= (ar_fire && ar_hits_hist);
    araddr_q1     <= s_axi_araddr;

    // q2
    ar_fire_q2    <= ar_fire_q1;
    rd_is_hist_q2 <= rd_is_hist_q1;
    araddr_q2     <= araddr_q1;

    // RDATA
    if (!s_axi_rvalid) begin
      if (ar_fire_q1 && !rd_is_hist_q1) begin
        s_axi_rvalid <= 1'b1; s_axi_rresp <= 2'b00;
        if (ar_in_reg) begin
            case (reg_off_q1)
              ADDR_ID       : s_axi_rdata <= 32'h5251_4131; // "RQA1"
              ADDR_STATUS   : s_axi_rdata <= {22'd0, HIST_EN, 7'd0, busy, metrics_valid_sticky};
              ADDR_RR_LO    : s_axi_rdata <= rr_count[31:0];
              ADDR_RR_HI    : s_axi_rdata <= rr_count[63:32];
              ADDR_DET_LO   : s_axi_rdata <= det_points[31:0];
              ADDR_DET_HI   : s_axi_rdata <= det_points[63:32];
              ADDR_DET_LINES: s_axi_rdata <= det_lines;
              ADDR_L_MAX    : s_axi_rdata <= {{(32-RUNW){1'b0}}, l_max};
              ADDR_LAM_LO   : s_axi_rdata <= lam_points[31:0];
              ADDR_LAM_HI   : s_axi_rdata <= lam_points[63:32];
              ADDR_LAM_LINES: s_axi_rdata <= lam_lines;
              ADDR_V_MAX    : s_axi_rdata <= {{(32-RUNW){1'b0}}, v_max};
              ADDR_CELLS_TGT: s_axi_rdata <= cells_target_reg;
              ADDR_CELLS_ACC: s_axi_rdata <= cells_accepted_dbg;
              default: s_axi_rdata <= 32'd0;
            endcase
        end else begin
             s_axi_rdata <= 32'd0;
        end
      end
      else if (ar_fire_q2 && rd_is_hist_q2) begin
        s_axi_rvalid <= 1'b1; s_axi_rresp <= 2'b00;
        s_axi_rdata  <= hist_rd_data;
      end
    end else if (s_axi_rvalid && s_axi_rready) begin
      s_axi_rvalid <= 1'b0;
    end
  end
end

endmodule
